        dia_names = {
            1: "domingo",
            2: "segunda-feira",
            3: "terça-feira",
            4: "quarta-feira",
            5: "quinta-feira",
            6: "sexta-feira",
            7: "sábado"
        }
        return dia_names[dia]
    else:
        return "valor inválido"
